    15→namespace Nethermind.Merge.Plugin
    16→{
    17→    public class MergeHeaderValidator : HeaderValidator
    18→    {
    19→        // https://eips.ethereum.org/EIPS/eip-3675#constants
    20→        private const int MaxExtraDataBytes = 32;
    21→
    22→        private readonly IPoSSwitcher _poSSwitcher;
    23→        private readonly IHeaderValidator _preMergeHeaderValidator;
    24→        private readonly IBlockTree _blockTree;
    25→
    26→        public MergeHeaderValidator(
    27→            IPoSSwitcher poSSwitcher,
    28→            IHeaderValidator preMergeHeaderValidator,
    29→            IBlockTree blockTree,
    30→            ISpecProvider specProvider,
    31→            ISealValidator sealValidator,
    32→            ILogManager logManager)
    33→            : base(blockTree, sealValidator, specProvider, logManager)
    34→        {
    35→            _poSSwitcher = poSSwitcher;
    36→            _preMergeHeaderValidator = preMergeHeaderValidator;
    37→            _blockTree = blockTree;
    38→        }
    39→
    40→        public override bool Validate(BlockHeader header, BlockHeader? parent, bool isUncle = false)
    41→        {
    42→            return Validate(header, parent, isUncle, out _);
    43→        }
    44→        public override bool Validate(BlockHeader header, BlockHeader? parent, bool isUncle, out string? error)
    45→        {
    46→            error = null;
    47→            return _poSSwitcher.IsPostMerge(header)
    48→                ? ValidateTheMergeChecks(header) && base.Validate(header, parent, isUncle, out error)
    49→                : ValidatePoWTotalDifficulty(header) && _preMergeHeaderValidator.Validate(header, parent, isUncle, out error);
    50→        }
    51→
    52→        protected override bool ValidateTotalDifficulty(BlockHeader parent, BlockHeader header, ref string? error) =>
    53→            _poSSwitcher.IsPostMerge(header) || base.ValidateTotalDifficulty(parent, header, ref error);
    54→
    55→        private bool ValidatePoWTotalDifficulty(BlockHeader header)
    56→        {
    57→            if (header.Difficulty == 0)
    58→            {
    59→                if (_logger.IsWarn) _logger.Warn($"Invalid block header {header.ToString(BlockHeader.Format.Short)} - zero difficulty for PoW block.");
    60→                return false;
    61→            }
    62→
    63→            return true;
    64→        }
    65→
    66→        private bool ValidateTheMergeChecks(BlockHeader header)
    67→        {
    68→            (bool IsTerminal, bool IsPostMerge) = _poSSwitcher.GetBlockConsensusInfo(header);
    69→            bool terminalTotalDifficultyChecks = ValidateTerminalTotalDifficultyChecks(header, IsTerminal);
    70→            bool valid = !IsPostMerge ||
    71→                        ValidateHeaderField(header, header.Difficulty, UInt256.Zero, nameof(header.Difficulty))
    72→                        && ValidateHeaderField(header, header.Nonce, 0u, nameof(header.Nonce))
    73→                        && ValidateHeaderField(header, header.UnclesHash, Keccak.OfAnEmptySequenceRlp, nameof(header.UnclesHash));
    74→
    75→            return terminalTotalDifficultyChecks && valid;
    76→        }
    77→
    78→        protected override bool ValidateExtraData(BlockHeader header, BlockHeader? parent, IReleaseSpec spec, bool isUncle, ref string? error)
    79→        {
    80→            if (_poSSwitcher.IsPostMerge(header))
    81→            {
    82→                if (header.ExtraData.Length > MaxExtraDataBytes)
    83→                {
    84→                    if (_logger.IsWarn) _logger.Warn($"Invalid block header {header.ToString(BlockHeader.Format.Short)} - the {nameof(header.ExtraData)} exceeded max length of {MaxExtraDataBytes}.");
    85→                    error = BlockErrorMessages.InvalidExtraData;
    86→                    return false;
    87→                }
    88→
    89→                return true;
    90→            }
    91→
    92→            return base.ValidateExtraData(header, parent, spec, isUncle, ref error);
    93→        }
    94→
    95→        private bool ValidateTerminalTotalDifficultyChecks(BlockHeader header, bool isTerminal)
    96→        {
    97→            if ((header.TotalDifficulty ?? 0) == 0 || _poSSwitcher.TerminalTotalDifficulty is null)
    98→            {
    99→                return true;
   100→            }
   101→
   102→            bool isValid = true;
   103→            bool isPostMerge = header.IsPostMerge;
   104→            if (!isPostMerge && !isTerminal)
   105→            {
   106→                if (header.TotalDifficulty >= _poSSwitcher.TerminalTotalDifficulty)
   107→                {
   108→                    isValid = false;
   109→                }
   110→            }
   111→            else if (header.TotalDifficulty < _poSSwitcher.TerminalTotalDifficulty)
   112→            {
   113→                isValid = false;
   114→            }
   115→
   116→            if (!isValid)
   117→            {
   118→                if (_logger.IsWarn) _logger.Warn($"Invalid block header {header.ToString(BlockHeader.Format.Short)} - total difficulty is incorrect because of TTD, TerminalTotalDifficulty: {_poSSwitcher.TerminalTotalDifficulty}, IsPostMerge {header.IsPostMerge} IsTerminalBlock: {isTerminal}");
   119→            }
   120→
   121→            return isValid;
   122→        }
   123→
   124→        private bool ValidateHeaderField<T>(BlockHeader header, T value, T expected, string name)
   125→        {
   126→            if (!Equals(value, expected))
   127→            {
   128→                if (_logger.IsWarn) _logger.Warn($"Invalid block header {header.ToString(BlockHeader.Format.Full)} - the {name} is incorrect expected {expected}, got {value}. TransitionFinished: {_poSSwitcher.TransitionFinished}, TTD: {_specProvider.TerminalTotalDifficulty}, IsTerminal: {header.IsTerminalBlock(_specProvider)}");
