    45→            return header.Hash == actualHash;
    46→        }
    47→
    48→        public static bool ValidateHash(BlockHeader header) => ValidateHash(header, out _);
    49→
    50→        private bool ValidateHash(BlockHeader header, ref string? error)
    51→        {
    52→            bool hashAsExpected = ValidateHash(header);
    53→
    54→            if (!hashAsExpected)
    55→            {
    56→                if (_logger.IsWarn) _logger.Warn($"Invalid block header ({header.Hash}) - invalid block hash");
    57→                error = BlockErrorMessages.InvalidHeaderHash(header.Hash, header.CalculateHash());
    58→                return false;
